"use strict";
const KB={"sources":{"kyosoku":{"short":"教則","title":"交通の方法に関する教則","publisher":"National Police Agency (国家公安委員会告示)","version":"Consolidated to the 4 Sep 2024 amendment (告示第37号)","url":"https://www.npa.go.jp/bureau/traffic/20241113kyousoku.pdf","kind":"primary","note":"Only readable up to 第4章第3節 through the tools used; 付表 not readable."},"rta":{"short":"道路交通法","title":"道路交通法 (Road Traffic Act)","publisher":"e-Gov","url":"https://laws.e-gov.go.jp/law/335AC0000000105","kind":"primary","note":"Statute text not read directly; articles cited via secondary sources."},"rta-order":{"short":"施行令","title":"道路交通法施行令 (Enforcement Order)","publisher":"e-Gov","url":"https://laws.e-gov.go.jp/law/335CO0000000270","kind":"primary","note":"Statute text not read directly (access request timed out)."},"kobe-ds":{"short":"Kobe Drivers Support","title":"車が通行するところ 車が通行してはいけないところ","publisher":"Kobe Drivers Support (driving-school study sheet)","url":"https://www.kobe-drivers-support.com/doc/department-passable-inpassable.pdf","kind":"secondary"},"iac":{"short":"IAC driving school","title":"教習項目４【車が通行するところ、車が通行してはいけないところ】","publisher":"IAC driving school","url":"https://www.iac-ds.co.jp/oyakudachi01004/","kind":"secondary"},"mpd-signs":{"short":"Tokyo MPD","title":"道路標識・道路標示","publisher":"Tokyo Metropolitan Police Department","url":"https://www.keishicho.metro.tokyo.lg.jp/kotsu/mark/hyoshiki.html","kind":"secondary"},"akita-bus":{"short":"Akita police","title":"バスレーン資料","publisher":"Akita Prefectural Police","url":"https://www.police.pref.akita.lg.jp/uploads/contents/news_0000004645_00/%E3%83%90%E3%82%B9%E3%83%AC%E3%83%BC%E3%83%B3%E8%B3%87%E6%96%99.PDF","kind":"secondary"},"kn-flash":{"short":"Kuruma News","title":"赤・黄の「点滅信号」の意味","publisher":"Kuruma News","url":"https://kuruma-news.jp/post/428898","kind":"secondary","note":"Quotes 道路交通法施行令 第2条."},"kn-bus":{"short":"Kuruma News","title":"バスレーンの「優先」「専用」何が違う?","publisher":"Kuruma News","url":"https://kuruma-news.jp/post/605892","kind":"secondary","note":"Paraphrases 道路交通法 第20条の2."},"general":{"short":"General knowledge","title":"General driving-school knowledge","publisher":"—","kind":"none","note":"Not checked against any source in this project. Verify against the school textbook."}},"rules":{"mark.kinds":{"id":"mark.kinds","en":"Road markings come in two kinds: regulatory markings (規制標示) ban or require; instruction markings (指示標示) show what you may do or where things are.","ja":"標示には規制標示と指示標示の2種類がある。","refs":[{"src":"kyosoku","loc":"第1章第2節 3(1)–(2)"}],"status":"primary","topic":"markings"},"mark.edge.yellow":{"id":"mark.edge.yellow","en":"A solid yellow line along the road edge means no stopping or parking.","ja":"路端の黄色の実線：駐停車禁止。","refs":[{"src":"kyosoku","loc":"付表3"}],"status":"unverified","topic":"markings"},"mark.edge.yellowdash":{"id":"mark.edge.yellowdash","en":"A broken yellow line along the road edge means no parking. Brief stops are allowed.","ja":"路端の黄色の破線：駐車禁止。","refs":[{"src":"kyosoku","loc":"付表3"}],"status":"unverified","topic":"markings"},"mark.lanearrows":{"id":"mark.lanearrows","en":"Arrows painted in a lane (進行方向別通行区分) say where traffic in that lane may go.","ja":"進行方向別通行区分：通行帯ごとに進行できる方向が指定される。","refs":[{"src":"kyosoku","loc":"付表3"}],"status":"unverified","topic":"markings"},"mark.diamond":{"id":"mark.diamond","en":"A diamond (◇) marking means a crosswalk or bicycle crossing ahead.","ja":"ひし形（◇）の標示：前方に横断歩道又は自転車横断帯がある。","refs":[{"src":"kyosoku","loc":"付表3"}],"status":"unverified","topic":"markings"},"mark.nostopzone":{"id":"mark.nostopzone","en":"Don't enter a no-stopping zone marking (停止禁止部分) if traffic ahead might leave you stopped inside it.","ja":"停止禁止部分：前方が混雑していてその中で停止するおそれがあるときは入ってはならない。","refs":[{"src":"rta","loc":"第50条"},{"src":"iac","loc":"P53"}],"status":"secondary","topic":"markings"},"road.keepleft":{"id":"road.keepleft","en":"Cars drive to the left of the centre of the road, or of the centre line where one is marked.","ja":"車は道路の中央（中央線があるときはその線）から左の部分を通行する。","refs":[{"src":"rta","loc":"第17条4項"},{"src":"kobe-ds","loc":"3"}],"status":"secondary","topic":"road"},"road.righthalf.obstruction":{"id":"road.righthalf.obstruction","en":"When road works or similar leave the left half too narrow, you may use the right half, crossing over as little as needed.","ja":"道路工事等で左側部分だけでは通行に十分な幅がないときは、右側部分にはみ出して通行できる（はみ出し方はできるだけ少なく）。","refs":[{"src":"rta","loc":"第17条5項"},{"src":"kobe-ds","loc":"3"}],"status":"secondary","topic":"road"},"road.overtake.6m":{"id":"road.overtake.6m","en":"Crossing the centre line to overtake is allowed only where your half of the road is under 6 m wide, the view is clear and oncoming traffic won't be obstructed, and no marking bans it.","ja":"左側部分の幅が6m未満で見通しがよく、反対方向の交通を妨げるおそれがないときは、追い越しのため右側にはみ出せる（禁止の標識・標示がある場合を除く）。","refs":[{"src":"rta","loc":"第17条5項"},{"src":"kobe-ds","loc":"3"}],"status":"secondary","topic":"road"},"road.yellowcentre":{"id":"road.yellowcentre","en":"A yellow centre line bans crossing into the right half to overtake.","ja":"黄色の中央線：追越しのための右側部分はみ出し通行禁止。","refs":[{"src":"rta","loc":"第17条5項"}],"status":"unverified","topic":"road"},"road.yellowcentre.obstruction":{"id":"road.yellowcentre.obstruction","en":"A yellow centre line does not stop you going round an obstruction that leaves your half too narrow.","ja":"黄色の中央線でも、工事等で左側部分の幅が十分でないときは、はみ出して通行できる。","refs":[{"src":"general","loc":""}],"status":"unverified","note":"Check against the textbook.","topic":"road"},"road.oneway":{"id":"road.oneway","en":"On a one-way road you may use the right side.","ja":"一方通行の道路では右側部分を通行できる。","refs":[{"src":"rta","loc":"第17条5項"},{"src":"kobe-ds","loc":"3"}],"status":"secondary","topic":"road"},"lane.two":{"id":"lane.two","en":"With two lanes in your direction, keep the right lane free for overtaking and drive in the left lane.","ja":"車両通行帯が2つのときは、右側を追越しのためにあけ、左側の通行帯を通行する。","refs":[{"src":"rta","loc":"第20条1項"},{"src":"kobe-ds","loc":"5"}],"status":"secondary","topic":"road"},"lane.three":{"id":"lane.three","en":"With three or more lanes, keep the rightmost free; slower vehicles keep left and faster ones move right.","ja":"3つ以上のときは、最も右側をあけ、速度の遅い車ほど左側の通行帯を通行する。","refs":[{"src":"rta","loc":"第20条1項"},{"src":"kobe-ds","loc":"5"}],"status":"secondary","topic":"road"},"lane.overtake.adjacent":{"id":"lane.overtake.adjacent","en":"To overtake, use the lane immediately to the right of the one you are in.","ja":"追越しをするときは、通行中の車両通行帯の直近の右側の通行帯を通行する。","refs":[{"src":"rta","loc":"第20条"},{"src":"kobe-ds","loc":"5"}],"status":"secondary","topic":"road"},"lane.yellowline":{"id":"lane.yellowline","en":"A yellow line between lanes means lane changes are banned.","ja":"黄色の車線境界線：進路変更禁止。","refs":[{"src":"rta","loc":"第26条の2 3項"}],"status":"unverified","note":"Check against the textbook.","topic":"road"},"bus.exclusive":{"id":"bus.exclusive","en":"An exclusive bus lane (専用通行帯) is closed to other vehicles while in force, except to turn.","ja":"路線バス等専用通行帯：指定時間中、右左折等の場合を除き、バス以外は通行できない。","refs":[{"src":"rta","loc":"第20条"},{"src":"akita-bus","loc":""}],"status":"secondary","topic":"road"},"bus.exclusive.leftturn":{"id":"bus.exclusive.leftturn","en":"You may enter an exclusive bus lane to turn left at the junction ahead.","ja":"左折するため交差点の手前で専用通行帯に入ることができる。","refs":[{"src":"mpd-signs","loc":""}],"status":"secondary","topic":"road"},"bus.priority":{"id":"bus.priority","en":"Other vehicles may use a bus priority lane (優先通行帯) but must give way to route buses.","ja":"路線バス等優先通行帯：一般車も通行できるが、路線バス等の通行を妨げてはならない。","refs":[{"src":"rta","loc":"第20条の2"},{"src":"mpd-signs","loc":""}],"status":"secondary","topic":"road"},"bus.priority.yield":{"id":"bus.priority.yield","en":"When a route bus comes up behind you in a priority lane, move promptly out of the lane.","ja":"後方から路線バス等が接近してきたときは、速やかに他の通行帯へ移る。","refs":[{"src":"rta","loc":"第20条の2"},{"src":"akita-bus","loc":""}],"status":"secondary","topic":"road"},"bus.priority.congested":{"id":"bus.priority.congested","en":"Don't enter a priority lane when traffic is too heavy for you to get out of a bus's way.","ja":"混雑していてバスの進行を妨げずに出られないときは、優先通行帯に入らない。","refs":[{"src":"rta","loc":"第20条の2"},{"src":"kn-bus","loc":""}],"status":"secondary","topic":"road"},"sidewalk.cross.stop":{"id":"sidewalk.cross.stop","en":"To cross the pavement to or from a roadside place, stop just before it every time, even with no one on it, and don't obstruct pedestrians.","ja":"道路に面した場所に出入りするため歩道等を横切るときは、その直前で一時停止し、歩行者の通行を妨げない。","refs":[{"src":"rta","loc":"第17条2項"},{"src":"kobe-ds","loc":"2"}],"status":"secondary","topic":"road"},"sig.green":{"id":"sig.green","en":"Steady green: cars may go straight, turn left or turn right. When turning right, give way to oncoming traffic going straight or turning left.","ja":"青色の灯火：自動車は直進・左折・右折できる。右折時は直進・左折する対向車の進行を妨げない。","refs":[{"src":"rta-order","loc":"第2条"},{"src":"rta","loc":"第37条"}],"status":"unverified","topic":"signals"},"sig.yellow":{"id":"sig.yellow","en":"Steady yellow: do not pass the stop position, unless you are so close that you cannot stop there safely.","ja":"黄色の灯火：停止位置で安全に停止できない場合を除き、停止位置を越えて進行してはならない。","refs":[{"src":"rta-order","loc":"第2条"}],"status":"secondary","note":"Wording from secondary explanations; statute not read.","topic":"signals"},"sig.red":{"id":"sig.red","en":"Steady red: vehicles must not pass the stop position.","ja":"赤色の灯火：車は停止位置を越えて進行してはならない。","refs":[{"src":"rta-order","loc":"第2条"}],"status":"unverified","topic":"signals"},"sig.arrow.green":{"id":"sig.arrow.green","en":"Green arrow: cars may proceed in the arrow's direction even while the main light is red or yellow. Bicycles may not proceed on a green right arrow.","ja":"青色の矢印：赤・黄でも矢印の方向へ進行できる。ただし自転車などは青の右向き矢印で進むことはできない。","refs":[{"src":"kyosoku","loc":"第3章第3節 3(3)イ(ア)"},{"src":"rta-order","loc":"第2条"}],"status":"primary","note":"Bicycle clause quoted from the 教則.","topic":"signals"},"sig.flash.red":{"id":"sig.flash.red","en":"Flashing red: vehicles must stop at the stop position, then may proceed.","ja":"赤色の灯火の点滅：車は停止位置で一時停止しなければならない。","refs":[{"src":"rta-order","loc":"第2条"},{"src":"kn-flash","loc":""}],"status":"secondary","topic":"signals"},"sig.flash.yellow":{"id":"sig.flash.yellow","en":"Flashing yellow: proceed while watching other traffic. Stopping is not required.","ja":"黄色の灯火の点滅：他の交通に注意して進行することができる。","refs":[{"src":"rta-order","loc":"第2条"},{"src":"kn-flash","loc":""}],"status":"secondary","topic":"signals"},"sig.leftboard":{"id":"sig.leftboard","en":"A white board with a blue left arrow lets vehicles turn left on red or yellow, watching other traffic, without obstructing pedestrians or cyclists crossing on green.","ja":"白地に青の左向き矢印の標示板：前方の信号が赤や黄でも周りの交通に注意して左折できる。青信号で横断する歩行者等を妨げてはならない。","refs":[{"src":"kyosoku","loc":"第1章第2節 1(4)"}],"status":"primary","topic":"signals"},"sig.lookahead":{"id":"sig.lookahead","en":"A red signal to the side does not mean yours is green. All directions can be red at once, and some signals change at different times (時差式). Read the signal facing you.","ja":"横の信号が赤でも前方の信号が青とは限らない。前方の信号を見ること。","refs":[{"src":"kyosoku","loc":"第1章第2節 1(2)"}],"status":"primary","topic":"signals"},"sig.ped.flashgreen":{"id":"sig.ped.flashgreen","en":"A flashing green pedestrian signal means the same as yellow.","ja":"歩行者用の信号の青の点滅は、黄信号と同じ意味。","refs":[{"src":"kyosoku","loc":"第2章第3節 2(3)"}],"status":"primary","topic":"signals"},"stoppos.line":{"id":"stoppos.line","en":"Where a stop line is marked, the stop position is just before the stop line.","ja":"停止線があるときは、停止線の直前が停止位置。","refs":[{"src":"rta-order","loc":"第2条"},{"src":"kyosoku","loc":"第1章第2節 3(2)"}],"status":"unverified","topic":"signals"},"stoppos.crosswalk":{"id":"stoppos.crosswalk","en":"With no stop line, the stop position is just before the crosswalk or bicycle crossing.","ja":"停止線がないときは、横断歩道等の直前が停止位置。","refs":[{"src":"rta-order","loc":"第2条"}],"status":"unverified","topic":"signals"},"stoppos.junction":{"id":"stoppos.junction","en":"With no stop line and no crosswalk, the stop position is just before the intersection.","ja":"停止線も横断歩道もないときは、交差点の直前が停止位置。","refs":[{"src":"rta-order","loc":"第2条"}],"status":"unverified","topic":"signals"},"sign.kinds":{"id":"sign.kinds","en":"Signs are main signs (本標識) and supplementary plates (補助標識). Main signs come in four kinds: regulatory, instruction, warning and guide.","ja":"標識には本標識と補助標識がある。本標識は規制・指示・警戒・案内の4種類。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(1)"}],"status":"primary","topic":"signs"},"sign.kind.kisei":{"id":"sign.kind.kisei","en":"Regulatory signs (規制標識) ban or require a specific way of driving, such as closing a road to vehicles or setting a maximum speed.","ja":"規制標識：特定の交通方法を禁止したり指定したりする。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(2)"}],"status":"primary","topic":"signs"},"sign.kind.shiji":{"id":"sign.kind.shiji","en":"Instruction signs (指示標識) show what you may do or where something is, such as where parking is allowed or where a crosswalk is.","ja":"指示標識：特定の交通方法ができることや決められた場所を示す。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(3)"}],"status":"primary","topic":"signs"},"sign.kind.keikai":{"id":"sign.kind.keikai","en":"Warning signs (警戒標識) give advance notice of a hazard or something to watch for, such as a railway crossing or road works.","ja":"警戒標識：道路上の危険や注意すべき状況を前もって知らせる。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(4)"}],"status":"primary","topic":"signs"},"sign.kind.annai":{"id":"sign.kind.annai","en":"Guide signs (案内標識) show place names, directions and distances.","ja":"案内標識：地点の名称、方面、距離などを示す。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(5)"}],"status":"primary","topic":"signs"},"sign.plate":{"id":"sign.plate","en":"Supplementary plates add to the main sign above them: the reason, times, days or vehicle types it applies to.","ja":"補助標識は本標識の意味を補足し、通常は本標識の下に付けられる。理由、時間、曜日、車の種類などを示す。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(6)"}],"status":"primary","topic":"signs"},"plate.abbrev.daika":{"id":"plate.abbrev.daika","en":"大貨 on a plate is the abbreviation for large freight vehicles (大型貨物自動車).","ja":"「大貨」は大型貨物自動車の略称。","refs":[{"src":"kyosoku","loc":"付表4"}],"status":"unverified","note":"付表4 not readable; abbreviation from general knowledge.","topic":"signs"},"sign.shinnyu":{"id":"sign.shinnyu","en":"車両進入禁止 (No entry): vehicles may not enter from the side where the sign stands. Pedestrians are not affected.","ja":"車両進入禁止：標識のある側から車両は進入できない。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(2)"}],"status":"unverified","note":"Category is primary; the precise meaning is from general knowledge.","topic":"signs"},"sign.tsukodome":{"id":"sign.tsukodome","en":"車両通行止め: the road is closed to all vehicles, in both directions.","ja":"車両通行止め：車両は通行できない。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(2)"}],"status":"unverified","topic":"signs"},"sign.ogata":{"id":"sign.ogata","en":"大型貨物自動車等通行止め: closed to large freight vehicles and similar. Ordinary cars may pass.","ja":"大型貨物自動車等通行止め：大型貨物自動車等は通行できない。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"sign.hokosha":{"id":"sign.hokosha","en":"歩行者専用: a pedestrian road. Vehicles may not drive in it except with a police permit or an exemption.","ja":"歩行者専用：歩行者用道路。許可を受けた車等を除き車は通行できない。","refs":[{"src":"rta","loc":"第8条, 第9条"},{"src":"kobe-ds","loc":""}],"status":"secondary","topic":"signs"},"sign.jitensha_hokosha":{"id":"sign.jitensha_hokosha","en":"自転車及び歩行者専用: only bicycles and pedestrians may use the road. Cars may not.","ja":"自転車及び歩行者専用：自転車と歩行者のみ通行できる。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"sign.shitei":{"id":"sign.shitei","en":"指定方向外進行禁止: you may only go in the directions of the arrows.","ja":"指定方向外進行禁止：矢印の方向以外へ進行できない。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"sign.tenkai":{"id":"sign.tenkai","en":"転回禁止 bans U-turns. Ordinary turns are not affected.","ja":"転回禁止：転回（Uターン）できない。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"sign.ippo":{"id":"sign.ippo","en":"一方通行: traffic may only travel in the arrow's direction.","ja":"一方通行：矢印の方向にのみ通行できる。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"sign.chusha_kinshi":{"id":"sign.chusha_kinshi","en":"駐車禁止 bans parking. Brief stops (停車) are still allowed.","ja":"駐車禁止：駐車できない（停車はできる）。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"sign.chuteisha_kinshi":{"id":"sign.chuteisha_kinshi","en":"駐停車禁止 bans both parking and stopping, however briefly, including to let passengers in or out.","ja":"駐停車禁止：駐車も停車もできない。","refs":[{"src":"general","loc":""}],"status":"unverified","topic":"signs"},"park.vs.stop":{"id":"park.vs.stop","en":"Loading or unloading for up to 5 minutes, or letting people in or out, counts as stopping (停車), not parking (駐車).","ja":"5分以内の荷物の積卸しや人の乗り降りのための停止は停車であり、駐車ではない。","refs":[{"src":"rta","loc":"第2条"}],"status":"unverified","topic":"signs"},"sign.tomare":{"id":"sign.tomare","en":"一時停止 (止まれ): stop just before the stop line every time, even if no one is coming, then go on.","ja":"一時停止：停止線の直前で必ず一時停止する。","refs":[{"src":"rta","loc":"第43条"}],"status":"unverified","topic":"signs"},"sign.jokou":{"id":"sign.jokou","en":"徐行 means driving at a speed at which you can stop at once. Driving schools teach this as roughly 10 km/h or less; that figure is a guideline, not law.","ja":"徐行：直ちに停止することができるような速度で進行すること（目安おおむね10km/h以下）。","refs":[{"src":"rta","loc":"第2条"}],"status":"unverified","topic":"signs"},"sign.speed.max":{"id":"sign.speed.max","en":"最高速度 sets a maximum. Any speed up to it is legal; you are not required to drive at it.","ja":"最高速度：その速度を超えてはならない（その速度で走る義務はない）。","refs":[{"src":"kyosoku","loc":"第1章第2節 2(2)"}],"status":"primary","note":"Kyosoku names maximum speed as a regulatory example.","topic":"signs"},"sign.keiteki":{"id":"sign.keiteki","en":"警笛鳴らせ: you must sound your horn here.","ja":"警笛鳴らせ：警笛を鳴らさなければならない。","refs":[{"src":"rta","loc":"第54条"}],"status":"unverified","topic":"signs"},"horn.restrict":{"id":"horn.restrict","en":"Use the horn only where a sign requires it or to avoid danger. Don't use it to hurry or warn pedestrians.","ja":"警笛は標識で指定された場所や危険を防止するためやむを得ないとき以外は鳴らしてはならない。","refs":[{"src":"rta","loc":"第54条"}],"status":"unverified","topic":"signs"},"ped.crosswalk.stop":{"id":"ped.crosswalk.stop","en":"When a pedestrian is crossing or about to cross at a crosswalk, stop just before it and let them cross.","ja":"横断歩道を横断し、又は横断しようとする歩行者がいるときは、その直前で一時停止し、通行を妨げない。","refs":[{"src":"rta","loc":"第38条"}],"status":"unverified","topic":"signs"}},"vocab":{"sign-kanji":{"$comment":"Road-sign vocabulary. status: 'unverified' = from general knowledge, not checked against the sign standard.","status":"unverified","kanji":[{"k":"止","read":"と(まる)・し","en":"stop","example":"止まれ"},{"k":"禁","read":"きん","en":"forbid","example":"禁止"},{"k":"車","read":"しゃ・くるま","en":"vehicle, car","example":"駐車"},{"k":"駐","read":"ちゅう","en":"stay (park)","example":"駐車"},{"k":"停","read":"てい","en":"halt, stop briefly","example":"停車"},{"k":"通","read":"つう・とお(る)","en":"pass through","example":"通行"},{"k":"行","read":"こう・い(く)","en":"go","example":"一方通行"},{"k":"進","read":"しん","en":"advance","example":"進入"},{"k":"入","read":"にゅう・い(る)","en":"enter","example":"進入禁止"},{"k":"速","read":"そく","en":"speed, fast","example":"速度"},{"k":"歩","read":"ほ・ある(く)","en":"walk","example":"歩道"},{"k":"道","read":"どう・みち","en":"road","example":"道路"},{"k":"線","read":"せん","en":"line","example":"停止線"},{"k":"優","read":"ゆう","en":"priority, superior","example":"優先"},{"k":"専","read":"せん","en":"exclusive","example":"専用"},{"k":"徐","read":"じょ","en":"slowly","example":"徐行"},{"k":"除","read":"じょ・のぞ(く)","en":"remove, except","example":"除く"},{"k":"転","read":"てん","en":"turn over, roll","example":"転回"},{"k":"追","read":"つい・お(う)","en":"chase","example":"追越し"},{"k":"横","read":"おう・よこ","en":"sideways, across","example":"横断"},{"k":"注","read":"ちゅう","en":"attention, pour","example":"注意"}],"words":[{"w":"止まれ","read":"とまれ","en":"Stop"},{"w":"徐行","read":"じょこう","en":"Go slowly"},{"w":"一時停止","read":"いちじていし","en":"Stop, then go on"},{"w":"進入禁止","read":"しんにゅうきんし","en":"No entry"},{"w":"車両通行止め","read":"しゃりょうつうこうどめ","en":"Closed to vehicles"},{"w":"駐車禁止","read":"ちゅうしゃきんし","en":"No parking"},{"w":"駐停車禁止","read":"ちゅうていしゃきんし","en":"No stopping or parking"},{"w":"駐車可","read":"ちゅうしゃか","en":"Parking allowed"},{"w":"一方通行","read":"いっぽうつうこう","en":"One way"},{"w":"転回禁止","read":"てんかいきんし","en":"No U-turn"},{"w":"追越し禁止","read":"おいこしきんし","en":"No overtaking"},{"w":"最高速度","read":"さいこうそくど","en":"Maximum speed"},{"w":"最低速度","read":"さいていそくど","en":"Minimum speed"},{"w":"警笛鳴らせ","read":"けいてきならせ","en":"Sound your horn"},{"w":"歩行者専用","read":"ほこうしゃせんよう","en":"Pedestrians only"},{"w":"横断歩道","read":"おうだんほどう","en":"Pedestrian crossing"},{"w":"停止線","read":"ていしせん","en":"Stop line"},{"w":"優先道路","read":"ゆうせんどうろ","en":"Priority road"},{"w":"踏切","read":"ふみきり","en":"Railway crossing"},{"w":"工事中","read":"こうじちゅう","en":"Road works"},{"w":"幅員減少","read":"ふくいんげんしょう","en":"Road narrows"},{"w":"安全地帯","read":"あんぜんちたい","en":"Safety zone"}],"readingDrill":["徐行","一時停止","進入禁止","駐停車禁止","一方通行","転回禁止","追越し禁止","最高速度","警笛鳴らせ","歩行者専用","横断歩道","優先道路","踏切","幅員減少","安全地帯","車両通行止め"],"plates":[{"text":"日・休日を除く","read":"にち・きゅうじつをのぞく","en":"Except Sundays and public holidays"},{"text":"8-20","read":"","en":"From 8:00 to 20:00"},{"text":"ここから","read":"","en":"The rule starts here"},{"text":"ここまで","read":"","en":"The rule ends here"},{"text":"区域内","read":"くいきない","en":"Applies throughout this zone"},{"text":"二輪を除く","read":"にりんをのぞく","en":"Except two-wheelers"},{"text":"大型等","read":"おおがたとう","en":"Large vehicles and similar"},{"text":"前方優先道路","read":"ぜんぽうゆうせんどうろ","en":"Priority road ahead"},{"text":"通学路","read":"つうがくろ","en":"School route"},{"text":"自転車を除く","read":"じてんしゃをのぞく","en":"Except bicycles"}],"build":[{"w":"徐行","tiles":["徐","行"],"decoys":["除","街"]},{"w":"止まれ","tiles":["止","まれ"],"decoys":["上","るな"]},{"w":"駐車禁止","tiles":["駐","車","禁","止"],"decoys":["注","林"]},{"w":"駐停車禁止","tiles":["駐","停","車","禁","止"],"decoys":["亭","注"]},{"w":"進入禁止","tiles":["進","入","禁","止"],"decoys":["人","近"]},{"w":"一方通行","tiles":["一","方","通","行"],"decoys":["万","道"]},{"w":"最高速度","tiles":["最","高","速","度"],"decoys":["連","席"]},{"w":"歩行者専用","tiles":["歩","行","者","専","用"],"decoys":["博","走"]},{"w":"横断歩道","tiles":["横","断","歩","道"],"decoys":["構","通"]},{"w":"優先道路","tiles":["優","先","道","路"],"decoys":["憂","洗"]}]}}};
